function publicApproach(profile, commonHqId) {
  const frame = profile.latest;
  const hq = frame?.message.view.entities.find(entity => entity.id === commonHqId && entity.hp > 0);
  if (!hq) return null;
  const groups = [2, 3].map(side => frame.message.view.entities.filter(entity => entity.side === side && entity.owner === side && entity.kind === 'unit' && entity.role !== 'worker' && entity.hp > 0 && (entity.level ?? 0) === (hq.level ?? 0) && Math.hypot(entity.x - hq.x, entity.y - hq.y) <= 12));
  return groups.every(group => group.length >= 2) ? {frame, hq, groups} : null;

